const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const toast=(message)=>{const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2400)};
let projectState=JSON.parse(localStorage.getItem('skyclip-project')||'{}');
const API_BASE=location.protocol.startsWith('http')?location.origin:'http://localhost:8787';
async function syncProjectList(){try{const response=await fetch(`${API_BASE}/api/projects`);if(!response.ok)return;const data=await response.json();const projects=data.projects||[];const first=projects[0];if(!first)return;const card=$('.project-card');if(card){const title=card.querySelector('.project-meta strong');const badge=card.querySelector('.project-badge');if(title)title.textContent=first.title;if(badge){badge.textContent=first.status==='ready'?'준비 완료':first.status==='processing'?'처리 중':'대기 중';badge.classList.toggle('muted',first.status!=='ready')}}const list=$('.library-list');if(list&&projects.length){projects.forEach((project,index)=>{const row=list.querySelectorAll('.library-row')[index]||document.createElement('button');row.className='library-row open-project';row.innerHTML=`<span><span class="mini-thumb t${(index%3)+1}"></span><strong>${project.title}</strong></span><span class="status ${project.status==='ready'?'progress-status':project.status==='failed'?'error-status':'draft-status'}">${project.status==='ready'?'준비 완료':project.status==='processing'?'처리 중':project.status==='failed'?'처리 실패':'대기 중'}</span><span>${new Date(project.createdAt).toLocaleString('ko-KR')}</span><span>9:16</span><span>↗</span>`;if(!row.parentElement)list.appendChild(row);row.onclick=openEditor})}}catch(error){console.info('프로젝트 목록은 로컬 화면을 사용합니다.')}}
syncProjectList();
function saveProject(extra={}){projectState={...projectState,...extra,updatedAt:new Date().toISOString()};localStorage.setItem('skyclip-project',JSON.stringify(projectState));return projectState}
async function saveEditorState(extra={}){const state={captions:JSON.parse(localStorage.getItem('skyclip-captions')||'[]'),...extra};saveProject({editorState:state});if(projectState.id){try{await fetch(`${API_BASE}/api/projects/${projectState.id}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({editorState:state,captions:state.captions})})}catch(error){}}}
function applyCaptionProject(project){if(!Array.isArray(project.captions))return;project.captions.forEach((caption,index)=>{const line=$$('.transcript p')[index];if(line){line.textContent=caption;if(project.captionCues?.[index]){line.dataset.time=`00:${String(project.captionCues[index].start).padStart(2,'0')}`;line.dataset.end=project.captionCues[index].end}}});localStorage.setItem('skyclip-captions',JSON.stringify(project.captions));if(project.captionCues)localStorage.setItem('skyclip-cues',JSON.stringify(project.captionCues))}
const cueEditor=document.createElement('div');cueEditor.className='cue-editor';cueEditor.innerHTML='<span>선택 자막 구간</span><label>시작 <input id="cueStart" type="number" min="0" max="999" step="1" value="0"></label><label>종료 <input id="cueEnd" type="number" min="1" max="999" step="1" value="3"></label><button id="cueSave">구간 저장</button>';$('.transcript').insertAdjacentElement('afterend',cueEditor);let activeCue=0;let cues=JSON.parse(localStorage.getItem('skyclip-cues')||'[{"start":0,"end":3},{"start":3,"end":9},{"start":9,"end":16}]');function selectCue(index){activeCue=index;const cue=cues[index]||{start:0,end:3};$('#cueStart').value=cue.start;$('#cueEnd').value=cue.end}$$('.transcript p').forEach((p,index)=>p.addEventListener('contextmenu',e=>{e.preventDefault();selectCue(index);toast(`${index+1}번째 자막 구간을 선택했습니다.`)}));$('#cueSave').addEventListener('click',()=>{const start=Number($('#cueStart').value),end=Number($('#cueEnd').value);if(end<=start){toast('종료 시간은 시작 시간보다 커야 합니다.');return}cues[activeCue]={start,end};localStorage.setItem('skyclip-cues',JSON.stringify(cues));const line=$$('.transcript p')[activeCue];if(line){line.dataset.time=`00:${String(start).padStart(2,'0')}`;line.dataset.end=end}saveEditorState({captionCues:cues});toast('자막 구간을 저장했습니다.')});
const creditBadge=document.createElement('button');creditBadge.className='credit-badge';creditBadge.textContent='✦ 크레딧 300';creditBadge.addEventListener('click',()=>toast('현재 사용 가능한 크레딧은 300입니다.'));$('.top-actions').prepend(creditBadge);
const notifyButton=document.createElement('button');notifyButton.className='icon-btn';notifyButton.textContent='🔔';notifyButton.onclick=async()=>{if(!projectState.id){toast('아직 프로젝트 알림이 없습니다.');return}try{const data=await fetch(`${API_BASE}/api/projects/${projectState.id}/logs`).then(r=>r.json());const logs=(data.logs||[]).slice(-5).reverse();const seen=JSON.parse(localStorage.getItem('skyclip-seen-logs')||'[]');const unread=logs.filter(log=>!seen.includes(log.at)).length;const panel=document.createElement('div');panel.className='notice-panel';panel.innerHTML=`<div class="notice-box"><button class="notice-close">×</button><p class="eyebrow">최근 알림 ${unread?`· ${unread}개 새 알림`:''}</p>${logs.map(log=>`<div class="notice-row"><small>${new Date(log.at).toLocaleTimeString('ko-KR')}</small><span>${log.message}</span></div>`).join('')||'<p>알림이 없습니다.</p>'}</div>`;document.body.appendChild(panel);panel.querySelector('.notice-close').onclick=()=>{localStorage.setItem('skyclip-seen-logs',JSON.stringify(logs.map(log=>log.at)));panel.remove()}}catch(error){toast('알림을 불러오지 못했습니다.')}};$('.top-actions').prepend(notifyButton);
const creditInfo=document.createElement('button');creditInfo.className='credit-info';creditInfo.textContent='ⓘ 예상 소모량: 영상 길이 1분당 10 크레딧';creditInfo.onclick=()=>toast('현재 잔액 300 크레딧 · 예상 소모량은 영상 길이에 따라 계산됩니다.');$('.upload-panel').append(creditInfo);
function updateCreditEstimate(duration){if(!Number.isFinite(duration))return;const cost=Math.max(10,Math.ceil(duration/60)*10);creditInfo.textContent=`ⓘ 예상 소모량: 약 ${cost} 크레딧 · 현재 잔액 300`;creditInfo.dataset.cost=cost}
const renderStatus=document.createElement('span');renderStatus.className='render-status';renderStatus.textContent='렌더 준비됨';$('.editor-actions').prepend(renderStatus);const downloadRender=document.createElement('button');downloadRender.className='ghost';downloadRender.textContent='결과 받기';downloadRender.addEventListener('click',downloadRenderedProject);$('.editor-actions').insertBefore(downloadRender,$('#exportBtn'));
const renderProgressTrack=document.createElement('span');renderProgressTrack.className='render-progress-track';renderProgressTrack.innerHTML='<i></i>';$('.editor-actions').prepend(renderProgressTrack);async function updateProgressBar(){if(!projectState.id)return;try{const project=await fetch(`${API_BASE}/api/projects/${projectState.id}`).then(r=>r.json());renderProgressTrack.querySelector('i').style.width=`${project.exportProgress||0}%`}catch(error){}}setInterval(()=>{if(document.visibilityState!=='hidden')updateProgressBar()},1200);updateProgressBar();
const logPanel=document.createElement('div');logPanel.className='log-panel';logPanel.innerHTML='<p class="eyebrow">처리 로그</p><div id="projectLogs">프로젝트 로그를 불러오는 중…</div>';$('.inspector').append(logPanel);async function refreshProjectLogs(){if(!projectState.id)return;try{const data=await fetch(`${API_BASE}/api/projects/${projectState.id}/logs`).then(r=>r.json());$('#projectLogs').innerHTML=(data.logs||[]).slice(-6).reverse().map(log=>`<div><span>${new Date(log.at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})}</span>${log.message}</div>`).join('')||'<div>기록이 없습니다.</div>'}catch(error){}}setInterval(()=>{if(document.visibilityState!=='hidden')refreshProjectLogs()},1800);refreshProjectLogs();
const toolStrip=document.createElement('div');toolStrip.className='tool-strip';toolStrip.innerHTML='<span class="tool-strip-label">빠른 생성</span><button data-tool="이미지">▧ 이미지</button><button data-tool="영상">▣ 영상</button><button data-tool="배경음악">♫ 배경음악</button><button data-tool="음향효과">◌ 음향효과</button><button data-tool="목소리">◉ 목소리</button>';$('.upload-panel').append(toolStrip);toolStrip.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>toast(`${b.dataset.tool} 생성 도구는 다음 연결 단계에서 사용할 수 있습니다.`)));
const toolDialog=document.createElement('div');toolDialog.className='tool-dialog';toolDialog.innerHTML='<div class="tool-dialog-box"><button class="tool-close">×</button><p class="eyebrow">AI TOOL</p><h2 id="toolTitle">생성 도구</h2><p id="toolHint">프로젝트에 사용할 요소를 준비합니다.</p><textarea id="toolPrompt" placeholder="원하는 내용을 입력하세요…"></textarea><input id="toolFile" type="file" accept="image/*,video/*"/><button id="toolGenerate" class="primary">생성 시작</button></div>';document.body.appendChild(toolDialog);const openTool=tool=>{toolDialog.classList.add('show');$('#toolTitle').textContent=`${tool} 생성`;$('#toolHint').textContent=`${tool}에 사용할 설명을 입력하세요.`;$('#toolPrompt').value='';$('#toolFile').value='';$('#toolFile').style.display=tool==='이미지 생성'||tool==='영상 생성'?'block':'none';$('#toolPrompt').focus()};toolDialog.querySelector('.tool-close').onclick=()=>toolDialog.classList.remove('show');toolStrip.querySelectorAll('button').forEach(b=>b.onclick=()=>openTool(b.dataset.tool));$('#toolGenerate').onclick=async()=>{const prompt=$('#toolPrompt').value.trim(),file=$('#toolFile').files[0];if(!prompt&&!file){toast('설명이나 파일을 입력해 주세요.');return}if(file)await storeAssetFile(file);const assets=JSON.parse(localStorage.getItem('skyclip-assets')||'[]');assets.push({type:$('#toolTitle').textContent.replace(' 생성',''),prompt:prompt||file.name,fileName:file?.name||null,createdAt:new Date().toISOString()});localStorage.setItem('skyclip-assets',JSON.stringify(assets));toolDialog.classList.remove('show');toast('생성 요청을 저장했습니다.')};
function syncAssets(){const list=$('.asset-list');if(!list)return;const assets=JSON.parse(localStorage.getItem('skyclip-assets')||'[]');assets.slice(-8).reverse().forEach(asset=>{if([...list.querySelectorAll('.asset-row')].some(row=>row.dataset.prompt===asset.prompt))return;const row=document.createElement('div');row.className='asset-row';row.dataset.prompt=asset.prompt;row.innerHTML=`<span class="asset-icon purple-bg">✦</span><span><strong>${asset.type}</strong><small>${asset.prompt}</small></span><span>생성 요청 저장됨</span><button>•••</button>`;list.prepend(row)})}setInterval(syncAssets,1000);syncAssets();
document.addEventListener('click',e=>{const row=e.target.closest('.asset-row[data-prompt]');if(!row)return;const type=row.querySelector('strong')?.textContent||'';if(type.includes('음악')||type.includes('음향')){const item=$('.audio-item');if(item){$$('.audio-item').forEach(x=>x.classList.remove('active'));item.classList.add('active');saveEditorState({audio:row.dataset.prompt});toast('선택한 에셋을 오디오 트랙에 넣었습니다.')}}else if(type.includes('이미지')||type.includes('영상')){$('#videoLabel').textContent=row.dataset.prompt;videoStage.classList.add('asset-selected');saveEditorState({visualAsset:{type,prompt:row.dataset.prompt}});toast('선택한 에셋을 영상 트랙에 넣었습니다.')}});
document.addEventListener('dblclick',async e=>{const row=e.target.closest('.asset-row[data-prompt]');if(!row)return;const assets=JSON.parse(localStorage.getItem('skyclip-assets')||'[]');const asset=assets.find(x=>x.prompt===row.dataset.prompt);if(!asset?.fileName)return;try{const db=await openVideoStore();const request=db.transaction('videos').objectStore('videos').get(`asset:${asset.fileName}`);request.onsuccess=()=>{if(request.result){const link=document.createElement('a');link.href=URL.createObjectURL(request.result);link.download=asset.fileName;link.click();toast('에셋 파일을 내려받았습니다.')}}}catch(error){toast('에셋 파일을 찾을 수 없습니다.')}});
document.addEventListener('contextmenu',async e=>{const row=e.target.closest('.asset-row[data-prompt]');if(!row)return;e.preventDefault();const assets=JSON.parse(localStorage.getItem('skyclip-assets')||'[]');const asset=assets.find(x=>x.prompt===row.dataset.prompt);if(!asset)return;const renamed=window.prompt('에셋 이름을 입력하세요.',asset.prompt);if(!renamed||renamed===asset.prompt)return;asset.prompt=renamed;localStorage.setItem('skyclip-assets',JSON.stringify(assets));if(projectState.id){try{await fetch(`${API_BASE}/api/projects/${projectState.id}/assets`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...asset,renamedFrom:row.dataset.prompt})})}catch(error){}}syncAssets();toast('에셋 이름을 변경했습니다.')});
document.addEventListener('click',async e=>{const button=e.target.closest('.asset-row button');if(!button)return;const row=button.closest('.asset-row');const prompt=row?.dataset.prompt;if(!prompt||!window.confirm('이 에셋을 삭제할까요?'))return;const assets=JSON.parse(localStorage.getItem('skyclip-assets')||'[]').filter(asset=>asset.prompt!==prompt);localStorage.setItem('skyclip-assets',JSON.stringify(assets));if(projectState.id){try{await fetch(`${API_BASE}/api/projects/${projectState.id}/assets`,{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({prompt})})}catch(error){}}row.remove();toast('에셋을 삭제했습니다.')});
function showView(name){$$('.view').forEach(v=>v.classList.toggle('active-view',v.id===name+'View'));$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===name));$('#crumbTitle').textContent=name==='studio'?'New project':name[0].toUpperCase()+name.slice(1);}
$$('.nav-item').forEach(n=>n.addEventListener('click',()=>showView(n.dataset.view)));
$$('[data-view]').filter(e=>!e.classList.contains('nav-item')).forEach(n=>n.addEventListener('click',()=>showView(n.dataset.view)));
async function openEditor(){showView('editor');$('#crumbTitle').textContent=projectState.title||'새 프로젝트';if(projectState.id){try{const response=await fetch(`${API_BASE}/api/projects/${projectState.id}`);if(response.ok){const project=await response.json();if(project.title)$('#videoLabel').textContent=project.title;if(Array.isArray(project.captions))project.captions.forEach((caption,index)=>{const line=$$('.transcript p')[index];if(line)line.textContent=caption});const state=project.editorState||{};if(state.captionStyle){$$('.style-chip').forEach(x=>x.classList.toggle('active',x.textContent===state.captionStyle))}if(state.audio){$$('.audio-item').forEach(x=>x.classList.toggle('active',x.querySelector('strong')?.textContent===state.audio))}if(Number.isFinite(state.cutAt)&&videoPreview.duration){videoPreview.currentTime=state.cutAt}}}catch(error){}}}
$$('.open-project,.project-card').forEach(n=>n.addEventListener('click',openEditor));
$('#newProjectBtn').addEventListener('click',()=>{toast('새 프로젝트가 준비되었습니다. 영상을 추가하거나 링크를 붙여 넣어 주세요.');$('#sourceInput').focus()});
$('#newProjectBtn2').addEventListener('click',()=>{showView('studio');setTimeout(()=>$('#sourceInput').focus(),100)});
$('#backStudio').addEventListener('click',()=>showView('studio'));
$('#analyzeBtn').addEventListener('click',async()=>{const requestId=crypto.randomUUID();const val=$('#sourceInput').value.trim();if(!val){toast('영상 링크를 먼저 붙여 넣어 주세요.');$('#sourceInput').focus();return}const title=val.replace(/^https?:\/\//,'').split('/')[0].slice(0,28);saveProject({title,source:val});const btn=$('#analyzeBtn');btn.disabled=true;btn.textContent='분석 중…';toast('AI가 하이라이트와 자막 타이밍을 찾고 있습니다…');try{const response=await fetch(`${API_BASE}/api/projects`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title,source:val,creditCost:Number(creditInfo.dataset.cost||10),requestId})});if(response.ok){const project=await response.json();saveProject({id:project.id,status:project.status});const poll=setInterval(async()=>{try{const state=await fetch(`${API_BASE}/api/projects/${project.id}`).then(r=>r.json());saveProject({status:state.status,progress:state.progress});if(state.status==='ready'){clearInterval(poll);toast('서버 처리 완료 — 편집할 준비가 되었습니다.')}}catch(error){clearInterval(poll)}},500)}}catch(error){console.info('API 연결 전 로컬 모드로 계속합니다.')}setTimeout(()=>{btn.disabled=false;btn.textContent='분석하기';openEditor();toast('분석 완료 — 하이라이트 장면 3개를 찾았습니다.')},1200)});
const fileInput=$('#fileInput'),dropzone=$('#dropzone'),videoPreview=$('#videoPreview'),videoStage=$('#videoStage');
if(projectState.title){$('#videoLabel').textContent=projectState.title}
function openVideoStore(){return new Promise((resolve,reject)=>{const request=indexedDB.open('skyclip-media',1);request.onupgradeneeded=()=>request.result.createObjectStore('videos');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function storeVideo(file){try{const db=await openVideoStore();const tx=db.transaction('videos','readwrite');tx.objectStore('videos').put(file,'current');return true}catch(error){return false}}
async function storeAssetFile(file){try{const db=await openVideoStore();const tx=db.transaction('videos','readwrite');tx.objectStore('videos').put(file,`asset:${file.name}`);return true}catch(error){return false}}
async function restoreLatestAsset(){const assets=JSON.parse(localStorage.getItem('skyclip-assets')||'[]');const latest=[...assets].reverse().find(asset=>asset.fileName&&(!asset.projectId||asset.projectId===(projectState.id||'local')));if(!latest)return;try{const db=await openVideoStore();const request=db.transaction('videos').objectStore('videos').get(`asset:${latest.fileName}`);request.onsuccess=()=>{const file=request.result;if(!file)return;const url=URL.createObjectURL(file);if(file.type.startsWith('video/')){videoPreview.src=url;videoStage.classList.add('has-video')}else if(file.type.startsWith('image/')){videoStage.style.backgroundImage=`url(${url})`;videoStage.classList.add('asset-selected')}}}catch(error){}}
restoreLatestAsset();
$('#toolGenerate').addEventListener('click',()=>{setTimeout(()=>{const assets=JSON.parse(localStorage.getItem('skyclip-assets')||'[]');if(assets.length){assets[assets.length-1].projectId=projectState.id||'local';localStorage.setItem('skyclip-assets',JSON.stringify(assets))}},50)});
$('#toolGenerate').addEventListener('click',()=>{setTimeout(async()=>{const assets=JSON.parse(localStorage.getItem('skyclip-assets')||'[]');const asset=assets.at(-1);if(asset&&projectState.id){try{await fetch(`${API_BASE}/api/projects/${projectState.id}/assets`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(asset)})}catch(error){}}},100)});
async function restoreVideo(){try{const db=await openVideoStore();const request=db.transaction('videos').objectStore('videos').get('current');request.onsuccess=()=>{if(request.result){videoPreview.src=URL.createObjectURL(request.result);videoStage.classList.add('has-video');$('#videoLabel').textContent=request.result.name}}}catch(error){}}
restoreVideo();
const captionDownload=document.createElement('button');captionDownload.className='secondary full';captionDownload.textContent='↓ 자막 파일 내려받기';$('#regenBtn').insertAdjacentElement('afterend',captionDownload);
function formatTime(sec){if(!Number.isFinite(sec))return'00:37';const m=Math.floor(sec/60).toString().padStart(2,'0');const s=Math.floor(sec%60).toString().padStart(2,'0');return`${m}:${s}`}
async function renderLocalVideo(){if(!videoPreview.src||!window.MediaRecorder){toast('이 브라우저에서는 로컬 렌더링을 지원하지 않습니다.');return}const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1920;const ctx=canvas.getContext('2d');const stream=canvas.captureStream(30);const audio=videoPreview.captureStream?.().getAudioTracks?.()||[];audio.forEach(track=>stream.addTrack(track));const selectedAudio=projectState.editorState?.audioFile?await getStoredAudio(projectState.editorState.audioFile):null;let audioElement=null,audioContext=null,audioDestination=null;if(selectedAudio){audioElement=new Audio(URL.createObjectURL(selectedAudio));audioElement.loop=true;audioElement.volume=Number(projectState.editorState?.audioVolume??80)/100;audioContext=new AudioContext();const source=audioContext.createMediaElementSource(audioElement);audioDestination=audioContext.createMediaStreamDestination();source.connect(audioDestination);source.connect(audioContext.destination);audioDestination.stream.getAudioTracks().forEach(track=>stream.addTrack(track));await audioElement.play().catch(()=>{})}const chunks=[];const mimeType=MediaRecorder.isTypeSupported('video/webm;codecs=vp9,opus')?'video/webm;codecs=vp9,opus':MediaRecorder.isTypeSupported('video/webm;codecs=vp8,opus')?'video/webm;codecs=vp8,opus':'video/webm';const recorder=new MediaRecorder(stream,{mimeType});recorder.ondataavailable=e=>e.data.size&&chunks.push(e.data);const done=new Promise(resolve=>recorder.onstop=resolve);const previous=videoPreview.currentTime;const cuts=JSON.parse(localStorage.getItem('skyclip-cuts')||'[]');const cues=JSON.parse(localStorage.getItem('skyclip-cues')||'[]');let skipLock=false;const skipCuts=()=>{const hit=cuts.find(sec=>videoPreview.currentTime>=sec&&videoPreview.currentTime<sec+2);if(hit&&!skipLock){skipLock=true;const cue=cues.find(item=>item.start===hit);videoPreview.currentTime=cue?.end||hit+2;setTimeout(()=>skipLock=false,120)}};videoPreview.addEventListener('timeupdate',skipCuts);videoPreview.currentTime=0;await videoPreview.play();recorder.start();const draw=()=>{if(videoPreview.paused||videoPreview.ended)return;ctx.fillStyle='#09090b';ctx.fillRect(0,0,1080,1920);const ratio=Math.min(1080/videoPreview.videoWidth,1920/videoPreview.videoHeight);const w=videoPreview.videoWidth*ratio,h=videoPreview.videoHeight*ratio;ctx.drawImage(videoPreview,(1080-w)/2,(1920-h)/2,w,h);requestAnimationFrame(draw)};draw();await new Promise(resolve=>videoPreview.onended=resolve);recorder.stop();await done;videoPreview.removeEventListener('timeupdate',skipCuts);videoPreview.currentTime=previous;if(audioElement){audioElement.pause();audioElement.removeAttribute('src');audioContext?.close()}const blob=new Blob(chunks,{type:'video/webm'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`${projectState.title||'skyclip'}-세로영상.webm`;link.click();toast('세로형 영상 파일을 내려받았습니다.')}
async function loadVideo(file){if(!file||!file.type.startsWith('video/')){toast('MP4, MOV, 또는 WebM 영상을 선택해 주세요.');return}await storeVideo(file);const title=file.name;saveProject({title,source:'local-video'});try{const hasProject=Boolean(projectState.id);const response=await fetch(hasProject?`${API_BASE}/api/projects/${projectState.id}`:`${API_BASE}/api/projects`,{method:hasProject?'PUT':'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title,source:'local-video'})});if(response.ok){const project=await response.json();saveProject({id:project.id,status:project.status})}}catch(error){}videoPreview.src=URL.createObjectURL(file);videoStage.classList.add('has-video');$('#videoLabel').textContent=file.name;videoPreview.onloadedmetadata=()=>{$('#stageDuration').textContent=formatTime(videoPreview.duration);$('#currentTime').textContent='00:00';$('#stageCurrent').textContent='00:00';toast('영상이 준비되었습니다.');openEditor()}}
