function renderCutMarkers(){const timeline=$('.timeline');if(!timeline)return;timeline.querySelectorAll('.cut-marker').forEach(x=>x.remove());savedCuts.forEach((sec,index)=>{const marker=document.createElement('span');marker.className='cut-marker';marker.style.left=`calc(70px + ${(sec/37)*100}% - ${(sec/37)*86}px)`;marker.title=`컷 ${sec}초 · 드래그하여 이동`;marker.addEventListener('pointerdown',event=>{event.preventDefault();const move=e=>{const rect=timeline.getBoundingClientRect();const ratio=Math.max(0,Math.min(1,(e.clientX-rect.left-70)/(rect.width-86)));const next=Math.round(ratio*37);savedCuts[index]=next;marker.style.left=`calc(70px + ${(next/37)*100}% - ${(next/37)*86}px)`;marker.title=`컷 ${next}초 · 드래그하여 이동`};const up=()=>{localStorage.setItem('skyclip-cuts',JSON.stringify(savedCuts));snapshotCuts();saveEditorState({cuts:savedCuts});window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);toast('컷 위치를 저장했습니다.')};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up)});timeline.appendChild(marker)})}renderCutMarkers();
const cutHistory=[];let cutHistoryIndex=-1;function snapshotCuts(){cutHistory.splice(cutHistoryIndex+1);cutHistory.push([...(JSON.parse(localStorage.getItem('skyclip-cuts')||'[]'))]);cutHistoryIndex=cutHistory.length-1}function restoreCuts(value){localStorage.setItem('skyclip-cuts',JSON.stringify(value));$$('.transcript p').forEach(p=>p.classList.toggle('cut-line',value.includes(Number(p.dataset.time.split(':').pop()))));renderCutMarkers();saveEditorState({cuts:value});}snapshotCuts();const timelineActions=$$('.timeline-action');timelineActions[2]?.addEventListener('click',()=>{if(cutHistoryIndex<=0){toast('되돌릴 변경사항이 없습니다.');return}cutHistoryIndex--;restoreCuts(cutHistory[cutHistoryIndex]);toast('이전 편집으로 되돌렸습니다.')});timelineActions[3]?.addEventListener('click',()=>{if(cutHistoryIndex>=cutHistory.length-1){toast('다시 실행할 변경사항이 없습니다.');return}cutHistoryIndex++;restoreCuts(cutHistory[cutHistoryIndex]);toast('편집을 다시 실행했습니다.')});$$('.transcript p').forEach((p,i)=>{p.contentEditable='true';p.spellcheck=false;p.addEventListener('focus',()=>p.classList.add('editing-line'));p.addEventListener('blur',async()=>{const captions=JSON.parse(localStorage.getItem('skyclip-captions')||'[]');captions[i]=p.innerText;localStorage.setItem('skyclip-captions',JSON.stringify(captions));if(projectState.id){try{await fetch(`${API_BASE}/api/projects/${projectState.id}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({captions})})}catch(error){}}p.classList.remove('editing-line');toast('자막 수정사항을 저장했습니다.')})});
