async function addListDownloads(){try{const data=await fetch(`${API_BASE}/api/projects`).then(r=>r.json());document.querySelectorAll('.library-row').forEach((row,index)=>{const project=data.projects?.[index];if(!project||row.querySelector('.row-download')||project.exportStatus!=='ready')return;const button=document.createElement('button');button.className='row-download';button.textContent='다운로드';button.onclick=async e=>{e.stopPropagation();const file=await fetch(`${API_BASE}/api/projects/${project.id}/export`);if(file.ok){const link=document.createElement('a');link.href=URL.createObjectURL(await file.blob());link.download=`${project.title||'skyclip'}-render.mp4`;link.click();toast('결과 영상을 내려받았습니다.')}};row.appendChild(button)})}catch(error){}}
