const moreProjects=document.createElement('button');moreProjects.className='ghost more-projects';moreProjects.textContent='더보기';projectToolbar.appendChild(moreProjects);let projectLimit=6;moreProjects.onclick=()=>{projectLimit+=6;document.querySelectorAll('.library-row').forEach((row,index)=>{if(index<projectLimit&&row.style.display==='none')row.style.display='grid'});moreProjects.textContent=`더보기 (${projectLimit})`};
