$('#analyzeBtn').addEventListener('click',e=>{const cost=Number(creditInfo.dataset.cost||10);if(cost>300){e.preventDefault();e.stopImmediatePropagation();toast(`크레딧이 부족합니다. 예상 ${cost} · 현재 300`)}},true);
function recordCreditUsage(){const cost=Number(creditInfo.dataset.cost||10);const usage=JSON.parse(localStorage.getItem('skyclip-credit-history')||'[]');usage.push({projectId:projectState.id||null,title:projectState.title||'새 프로젝트',cost,createdAt:new Date().toISOString()});localStorage.setItem('skyclip-credit-history',JSON.stringify(usage));if(projectState.id)fetch(`${API_BASE}/api/projects/${projectState.id}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({creditCost:cost})}).catch(()=>{});toast(`${cost} 크레딧 사용 내역을 저장했습니다.`)}
$('#analyzeBtn').addEventListener('click',()=>setTimeout(recordCreditUsage,1500));
const creditPanel=document.createElement('section');creditPanel.className='credit-panel';creditPanel.innerHTML='<div><p class="eyebrow">크레딧 사용 내역</p><h2>최근 사용량</h2></div><div id="creditHistory"></div>';$('.studio-footer').insertAdjacentElement('afterend',creditPanel);function refreshCreditHistory(){const history=JSON.parse(localStorage.getItem('skyclip-credit-history')||'[]').slice(-5).reverse();$('#creditHistory').innerHTML=history.length?history.map(item=>`<div class="credit-row"><span>${item.title}</span><b>-${item.cost}</b><small>${new Date(item.createdAt).toLocaleDateString('ko-KR')}</small></div>`).join(''):'<p class="empty-history">아직 사용 내역이 없습니다.</p>'}setInterval(refreshCreditHistory,1200);refreshCreditHistory();
async function syncCreditHistory(){try{const data=await fetch(`${API_BASE}/api/credits`).then(r=>r.json());if(Number.isFinite(data.balance))creditBadge.textContent=`✦ 크레딧 ${data.balance}`;if(data.usage?.length){localStorage.setItem('skyclip-credit-history',JSON.stringify(data.usage));refreshCreditHistory()}}catch(error){}}setInterval(()=>{if(document.visibilityState!=='hidden')syncCreditHistory()},2000);syncCreditHistory();






$$('.style-chip').forEach(chip=>chip.addEventListener('click',()=>{const styleMap={'기본':'clean','바운스':'bounce','노래방':'karaoke','팝':'pop'};const style=styleMap[chip.textContent.trim()]||chip.textContent.trim().toLowerCase();videoStage.dataset.captionStyle=style;videoStage.classList.remove('caption-clean','caption-bounce','caption-karaoke','caption-pop');videoStage.classList.add(`caption-${style}`)}));
const audioPanel=$('#audioPanel');if(audioPanel&&!$('#audioVolume')){const volumeWrap=document.createElement('label');volumeWrap.className='audio-volume';volumeWrap.innerHTML='<span>오디오 볼륨</span><input id="audioVolume" type="range" min="0" max="100" value="80"><output>80%</output>';audioPanel.appendChild(volumeWrap);$('#audioVolume').addEventListener('input',e=>{volumeWrap.querySelector('output').textContent=`${e.target.value}%`;if(videoPreview)videoPreview.volume=Number(e.target.value)/100;saveEditorState({audioVolume:Number(e.target.value)})})}
if(audioPanel&&!$('#audioUpload')){const upload=document.createElement('label');upload.className='audio-upload';upload.innerHTML='＋ 오디오 파일 추가<input id="audioUpload" type="file" accept="audio/*" hidden>';audioPanel.appendChild(upload);$('#audioUpload').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;await storeAssetFile(file);const name=file.name;$$('.audio-item').forEach(x=>x.classList.remove('active'));const item=document.createElement('div');item.className='audio-item active';item.innerHTML=`<span>♫</span><div><strong>${name}</strong><small>내 오디오 · ${Math.round(file.size/1024)}KB</small></div><button>✓</button>`;audioPanel.insertBefore(item,upload);saveEditorState({audio:name,audioFile:name});toast('오디오 파일을 추가했습니다.')})}
async function getStoredAudio(name){try{const db=await openVideoStore();return await new Promise(resolve=>{const request=db.transaction('videos').objectStore('videos').get(`asset:${name}`);request.onsuccess=()=>resolve(request.result||null);request.onerror=()=>resolve(null)})}catch{return null}}document.addEventListener('keydown',event=>{if(!(event.ctrlKey||event.metaKey))return;const actions=$$('.timeline-action');if(event.key.toLowerCase()==='z'&&!event.shiftKey){event.preventDefault();actions[2]?.click()}else if((event.key.toLowerCase()==='z'&&event.shiftKey)||event.key.toLowerCase()==='y'){event.preventDefault();actions[3]?.click()}});
document.addEventListener('keydown',event=>{const tag=document.activeElement?.tagName;if(tag==='INPUT'||tag==='TEXTAREA'||document.activeElement?.isContentEditable)return;const key=event.key.toLowerCase();if(key===' '){event.preventDefault();$('#playBtn')?.click()}else if(key==='c'){event.preventDefault();$('#cutBtn')?.click()}else if(event.ctrlKey&&key==='enter'){event.preventDefault();$('#exportBtn')?.click()}});
if($('.editor-toolbar')&&!$('.shortcut-hint')){const hint=document.createElement('span');hint.className='shortcut-hint';hint.textContent='단축키: Space 재생 · C 컷 · Ctrl+Enter 내보내기 · Ctrl+Z 실행 취소';$('.editor-toolbar').appendChild(hint)}

// FikaClip-style result exploration: one source video produces several ranked clips.
